import axios, { AxiosRequestConfig } from 'axios';

const DOMAIN_API = process.env.REACT_APP_DOMAIN_API;
const PREFIX_API = process.env.REACT_APP_PREFIX_API;

export const AxiosInstance = axios.create({
  baseURL: `${DOMAIN_API}${PREFIX_API}`,
  timeout: 10000,
  // headers: {
  //   'Content-Type': 'application/json',
  //   'Access-Control-Allow-Origin': '*'
  // },
  withCredentials: true,
});

AxiosInstance.interceptors.request.use((request: AxiosRequestConfig) => {
  if (!request.headers) return;

  // request.headers['Access-Control-Allow-Origin'] = '*';
  // request.headers['Access-Control-Allow-Methods'] = 'GET, POST, PUT, DELETE, OPTIONS';
  // request.headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization';
  // request.headers['Access-Control-Allow-Credentials'] = true;
  request.headers['x-rapidapi-host'] = 'etsy-product.p.rapidapi.com';
  request.headers['x-rapidapi-key'] = '7f343e866amsh291afe5aa351b75p1ca9a5jsn27f05f3901f4';

  const token = localStorage.getItem('ACCESS-TOKEN');
  if (token) {
    request.headers['Authorization'] = `Bearer ${token}`;
  }

  return request;
}, (error) => {
  return Promise.reject(error);
});

AxiosInstance.interceptors.response.use(
  (response) => response,
  (error) => {
    // handle error
    if (error.response && error.response.status === 401) {
      localStorage.removeItem('ACCESS-TOKEN');

      return Promise.reject(error);
    }
  });

const APIService = {
  get(uri: string, options = {}) {
    return new Promise((resolve, reject) => {
      AxiosInstance.get(uri, {
        params: options,
      })
        .then((resp) => {
          return resolve(resp);
        })
        .catch((err) => {
          console.log("err", err)
          return reject(err);
        });
    });
  },

  post(uri: string, data = {}, moreConfigs = {}) {
    return new Promise((resolve, reject) => {
      AxiosInstance.post(uri, data, moreConfigs)
        .then((resp) => {
          resolve(resp);
        })
        .catch((err) => {
          reject(err);
        });
    });
  }
}


export default APIService;
